"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9849"],{118(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>h,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>c});var a=JSON.parse('{"id":"explain/avphone_faq","title":"AVPhone FAQ","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/explain/avphone_faq.md","sourceDirName":"explain","slug":"/explain/avphone_faq","permalink":"/personal-av-docs/docs/explain/avphone_faq","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/explain/avphone_faq.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"AVPhone FAQ","sidebar_label":"AVPhone FAQ","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/avphone_faq","format":"md"}}'),o=t(4848),i=t(8453);let s={title:"AVPhone FAQ",sidebar_label:"AVPhone FAQ",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/avphone_faq",format:"md"},r,c={},l=[];function d(e){let n={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(n.p,{children:[":::note Edition\n",(0,o.jsx)(n.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(n.a,{href:"https://doc.airvantage.net/av/avphone_faq",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsxs)(n.p,{children:["AVPhone FAQ\nGDPR FAQ\nProduct Page\nForum\nSearching...\nMatching results\nAVPhone FAQ\nWhat is AV Phone?\nPrerequisites\nGetting started\nFeatures\nHow does it work?\nSend data to AirVantage\nView data in your AirVantage account\nSend Alarm (alert message)\nCustomize the simulated data\nSource code access\nFrequently Asked Questions\nCompatible devices\nHow to select my AirVantage login server URL (eu.airvantage.net or na.airvantage.net)?\nHow can I modify the communication frequency?\nCan I change the variable and the system name?\nWhy my smartphone stops to send the GPS location?\nTroubleshooting\nFeedback/ Technical Support\nWhat is AV Phone?\nAV Phone is a mobile application, it sends data to AirVantage as a simulated object. By default, the app simulates a connected printer that sends mobile network data and simulated printing operations data to AirVantage periodically.\nIt provides an easy way to populate your AirVantage account with both mobile network and asset data, for platform evaluation use.\nAV Phone is available in 2 versions: Android and iOS, they are available for free download from the respective app store.\nPrerequisites\nA\nSmartphone or Tablet PC\n(see:\nCompatible devices\n)\nAn\nAirVantage account\n. Get a free trial account:\n",(0,o.jsx)(n.a,{href:"https://eu.airvantage.net/accounts/signup?type=AVEP",children:"https://eu.airvantage.net/accounts/signup?type=AVEP"}),"\nGetting started\nDownload \u201C\nSierra Wireless AV Phone\n\u201D from Google Play/ Apple App Store and install it on your phone\nWhen AV Phone opens, log in to your AirVantage account\nThe app will automatically create a system for your phone on AirVantage\nPlease do authorize the app to retrieve phone location\nToggle on the \u201CSend Data\u2026\u201D switch to start sending data! To stop sending data, simply toggle the \u201CSend data\u2026\u201D switch to the off state.\nThe data is now waiting for you in your AirVantage account! Check it out!\nFeatures\nBoth AV Phone apps offer the same functionalities, but they look slightly different:\niOS version\nAndroid version\nHow does it work?\nSend data to AirVantage\nTurn on the \u201CSend data\u2026\u201D switch to start sending data from your phone to AirVantage periodically. You can leave the app running in the background, it will continue sending data.\nTo stop sending data, toggle the \u201CSend data\u2026\u201D switch to the off state, or log out from the application.\nView data in your AirVantage account\nYou can find the data in your AirVantage account this way:\nUse a web browser to log in to your AirVantage account\nClick on the \u201CMonitor\u201D/ \u201CSystems\u201D\nClick on the system with your phone\u2019s name to see the details\nClick on the \u201CTimeline\u201D button to see all communications sent by your phone\nThe iOS version always starts by sending communications without data (Data point = 0). It will start sending the application data after a delay of max 2 minutes.\nPlease do not modify or delete your phone\u2019s system from the AirVantage web portal, this may impact the mobile app operation (as the app may no longer be able to identify the system on the AirVantage account).\nSend Alarm (alert message)\nYou can send an alert message to AirVantage by clicking on the \u201CSend Alarm\u201D switch. This alert is not associated with any data threshold, it is for illustrating the data push capability only.\nCustomize the simulated data\nThe iOS and Android version allow the users to store multiple simulated object profiles in the app, and activate anyone of it at any time.\nAndroid version:\nCreate a new simulated object as follows:\nClick on the Menu icon on the top left corner\nClick on \u201CSimulated objects\u201D / \u201CEdit\u201D\nClick on \u201CAdd\u201D to create a new object and fill in the descriptions (For example: Name: Compressor; Alarm: High pressure!; List of data: \u201CPressure\u201D, \u201CTemperature\u201D \u2026)\nClick on \u201CSave\u201D, then \u201CDone\u201D\nBack to the menu, you can now select this newly created object (e.g. Compressor) by clicking on it\nIn the object menu edition, you can resync all objects to AirVantage.\niOS version:\nCreate a new simulated object as follows:\nClick on the Menu icon on the top left corner\nClick on \u201CSimulated objects\u201D / \u201CEdit\u201D\nClick on \u201C+\u201D to create a new object and fill in the descriptions (For example: Name: Compressor; Alarm: High pressure!; List of data: \u201CPressure\u201D, \u201CTemperature\u201D\u2026)\nClick on \u201CSave\u201D, then \u201CDone\u201D\nBack to the menu, you can now select to active this newly created object (e.g. Compressor) by clicking on it\nSource code access\nThe Android version source code can be accessed on github\nhere\nunder the MIT License (see License.md file in the repository).\nFrequently Asked Questions\nCompatible devices\nAndroid devices running Android 5.1 and onwards\nApple iOS devices running iOS8 and onwards including\niphone 4S, 5 / 5S, 6 / 6+\niPad2 (Cellular only)\niPad Air / iPar Air 2\nHow to select my AirVantage login server URL (eu.airvantage.net or na.airvantage.net)?\nThis is the web address (URL) that you use to log in to your AirVantage account with a web browser. If you do not recall this information, refer to the welcome email message from Sierra Wireless upon the AirVantage account creation.\nHow can I modify the communication frequency?\nFor the iOS version, click on \u201CSettings\u201D of your phone. Look for \u201CAVPhone\u201D in the app list, and select the \u201CFrequency\u201D options : 1, 2, or 5 minutes.\nFor the Android version, click on the Menu, click on Settings and change the Push data period options: 1, 2, 5 or 15 minutes\nCan I change the variable and the system name?\nIf sending data about Printer suits the most of the use cases, you may want to customize the data label. The configure tab allows you to change these labels automatically.\nYou can see the data you can use by clicking on the Application Details in Monitor > System > System Details view > Application Details bubble.\nOn the iOS version\nYou can choose how to simulate each data by selecting up, down or string to respectively increment, decrease the value or not change it.\nOnly the labels are changed, the data id (or data path) are not modified. If you want to get it using the AirVantage API, nothing is required to be changed.\nOn the Android version\nYou can choice how to simulate each data by selecting increase indefinitely, decrease to zero, random or None. For the decrease to zero simulation, the value is reset to initial value when it reaches 0. You can choice also the data path for the value.\nThe label and the data path can be changed.\nClick on the\nSave\nbutton when you have finished\nYou can change the system name on AirVantage to fit your business case.\nWhy my smartphone stops to send the GPS location?\nYou mustn\u2019t put the application in background mode. In this case, the smartphone stops the application in order to save power.\nBe aware battery consumption is high in this case.\nTroubleshooting\nIf your app is frozen, you can close the app (on an iOS device, double tap the \u201CHome\u201D button to see the list of background apps, and remove AV Phone from this list) and re-open it again).\nFor the Android version, if you receive an\ninvalid user\nwhen you try to send data, you can try to resync all the objects to AirVantage (Menu > Edit > Resync All).\nFeedback/ Technical Support\nIf you have any feedback or question, please use the \u201CFeedback\u201D button in the AirVantage web portal to contact us.\nHope you enjoy using the AV Phone! Happy IoT building!"]})]})}function h(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var a=t(6540);let o={},i=a.createContext(o);function s(e){let n=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(i.Provider,{value:n},e.children)}}}]);